314	/// Build a ready-to-insert CostRecord with current timestamp and developer.
315	pub fn new_record(
316	    session_id: &str,
317	    model_id: &str,
318	    input_tokens: u64,
319	    output_tokens: u64,
320	    cache_read_tokens: u64,
321	    cache_write_tokens: u64,
322	    cost_usd: f64,
323	    pr_ref: Option<String>,
324	    feature_tag: Option<String>,
325	    project_path: &str,
326	) -> CostRecord {
327	    CostRecord {
328	        id: None,
329	        session_id: session_id.to_string(),
330	        model_id: model_id.to_string(),
331	        input_tokens,
332	        output_tokens,
333	        cache_read_tokens,
334	        cache_write_tokens,
335	        cost_usd,
336	        pr_ref,
337	        feature_tag,
338	        project_path: project_path.to_string(),
339	        developer_id: whoami(),
340	        timestamp: chrono::Utc::now().to_rfc3339(),
341	    }
342	}
