13	/// Configuration loaded from quality-rules.toml.
14	#[derive(Debug, Clone)]
15	pub struct QualityConfig {
16	    pub block_on: Vec<Severity>,
17	    /// Severities to report as warnings (does not block gate, used for output formatting).
18	    #[allow(dead_code)]
19	    pub warn_on: Vec<Severity>,
20	    pub denied_licenses: Vec<String>,
21	    pub allowed_licenses: Vec<String>,
22	    pub cache_ttl_hours: u64,
23	    pub offline_mode: bool,
24	    pub rate_limit_per_sec: u32,
25	    pub ignore_packages: Vec<String>,
26	    pub ignore_paths: Vec<String>,
27	}
28	
29	impl Default for QualityConfig {
30	    fn default() -> Self {
31	        Self {
32	            block_on: vec![Severity::Critical, Severity::High],
33	            warn_on: vec![Severity::Medium, Severity::Low],
34	            denied_licenses: vec!["GPL-3.0".to_string(), "AGPL-3.0".to_string()],
35	            allowed_licenses: vec![
36	                "MIT".to_string(),
37	                "Apache-2.0".to_string(),
38	                "BSD-2-Clause".to_string(),
39	                "BSD-3-Clause".to_string(),
40	                "ISC".to_string(),
41	            ],
42	            cache_ttl_hours: 24,
43	            offline_mode: false,
44	            rate_limit_per_sec: 10,
45	            ignore_packages: vec![],
46	            ignore_paths: vec![
47	                "node_modules/**".to_string(),
48	                "vendor/**".to_string(),
49	                ".git/**".to_string(),
