54	
55	impl QualityConfig {
56	    /// Load from the first found config file:
57	    /// 1. `data/quality-rules.toml` (project-local)
58	    /// 2. `~/.config/rtk/quality-rules.toml` (user-global)
59	    /// Falls back to Default on any parse error.
60	    pub fn load() -> Self {
61	        let candidates: Vec<PathBuf> = vec![
62	            PathBuf::from("data/quality-rules.toml"),
63	            dirs::config_dir()
64	                .unwrap_or_else(|| PathBuf::from("."))
65	                .join("rtk")
66	                .join("quality-rules.toml"),
67	        ];
68	
69	        for path in &candidates {
70	            if let Ok(content) = std::fs::read_to_string(path) {
71	                if let Ok(cfg) = parse_toml_config(&content) {
72	                    return cfg;
73	                }
74	            }
75	        }
76	
77	        Self::default()
78	    }
79	
80	    /// True if a finding at `severity` should block the gate.
81	    pub fn is_blocking(&self, sev: Severity) -> bool {
82	        self.block_on.contains(&sev)
83	    }
84	}
85	
86	fn parse_toml_config(content: &str) -> Result<QualityConfig> {
87	    let doc: toml::Value = toml::from_str(content)?;
88	
89	    fn str_vec(val: &toml::Value, path: &[&str]) -> Vec<String> {
90	        let mut v = val;
91	        for key in path {
92	            match v.get(key) {
93	                Some(next) => v = next,
94	                None => return vec![],
95	            }
96	        }
97	        v.as_array()
98	            .map(|arr| {
99	                arr.iter()
100	                    .filter_map(|e| e.as_str().map(|s| s.to_string()))
101	                    .collect()
102	            })
103	            .unwrap_or_default()
104	    }
105	
106	    fn get_u64(val: &toml::Value, path: &[&str], default: u64) -> u64 {
107	        let mut v = val;
108	        for key in path {
109	            match v.get(key) {
110	                Some(next) => v = next,
111	                None => return default,
112	            }
113	        }
114	        v.as_integer().map(|i| i as u64).unwrap_or(default)
115	    }
116	
117	    fn get_bool(val: &toml::Value, path: &[&str], default: bool) -> bool {
118	        let mut v = val;
119	        for key in path {
120	            match v.get(key) {
121	                Some(next) => v = next,
122	                None => return default,
123	            }
124	        }
125	        v.as_bool().unwrap_or(default)
126	    }
127	
128	    let block_strs = str_vec(&doc, &["thresholds", "block_on"]);
129	    let warn_strs = str_vec(&doc, &["thresholds", "warn_on"]);
130	
131	    let parse_sev = |s: &str| match s {
132	        "critical" => Some(Severity::Critical),
133	        "high" => Some(Severity::High),
134	        "medium" => Some(Severity::Medium),
135	        "low" => Some(Severity::Low),
136	        _ => None,
137	    };
138	
139	    let block_on: Vec<Severity> = block_strs.iter().filter_map(|s| parse_sev(s)).collect();
140	    let warn_on: Vec<Severity> = warn_strs.iter().filter_map(|s| parse_sev(s)).collect();
141	
142	    Ok(QualityConfig {
143	        block_on: if block_on.is_empty() {
144	            vec![Severity::Critical, Severity::High]
145	        } else {
146	            block_on
147	        },
148	        warn_on: if warn_on.is_empty() {
149	            vec![Severity::Medium, Severity::Low]
150	        } else {
151	            warn_on
152	        },
153	        denied_licenses: str_vec(&doc, &["licenses", "denied"]),
154	        allowed_licenses: str_vec(&doc, &["licenses", "allowed"]),
155	        cache_ttl_hours: get_u64(&doc, &["registries", "cache_ttl_hours"], 24),
156	        offline_mode: get_bool(&doc, &["registries", "offline_mode"], false),
157	        rate_limit_per_sec: get_u64(&doc, &["registries", "rate_limit_per_sec"], 10) as u32,
158	        ignore_packages: str_vec(&doc, &["ignore", "packages"]),
159	        ignore_paths: str_vec(&doc, &["ignore", "paths"]),
160	    })
161	}
