355	/// Simple glob-style ignore: supports `**` prefix patterns.
356	fn should_ignore(path: &str, patterns: &[String]) -> bool {
357	    let normalized = path.replace('\\', "/");
358	    for pat in patterns {
359	        let seg = pat.trim_start_matches("**/").trim_end_matches("/**");
360	        if normalized.starts_with(&format!("{}/", seg))
361	            || normalized.contains(&format!("/{}/", seg))
362	            || normalized.ends_with(&format!("/{}", seg))
363	            || normalized == seg
364	        {
365	            return true;
366	        }
367	    }
368	    false
369	}
