206	// ── Gemini hook ───────────────────────────────────────────────
207	
208	/// Run the Gemini CLI BeforeTool hook.
209	pub fn run_gemini() -> Result<()> {
210	    let input = read_stdin_limited()?;
211	
212	    let json: Value = serde_json::from_str(&input).context("Failed to parse hook input as JSON")?;
213	
214	    let tool_name = json.get("tool_name").and_then(|v| v.as_str()).unwrap_or("");
215	
216	    if tool_name != "run_shell_command" {
217	        print_allow();
218	        return Ok(());
219	    }
220	
221	    let cmd = json
222	        .pointer("/tool_input/command")
223	        .and_then(|v| v.as_str())
224	        .unwrap_or("");
225	
226	    if cmd.is_empty() {
227	        print_allow();
228	        return Ok(());
229	    }
230	
231	    // Check deny rules — Gemini CLI only supports allow/deny (no ask mode).
232	    if permissions::check_command(cmd) == PermissionVerdict::Deny {
233	        let _ = writeln!(
234	            io::stdout(),
235	            r#"{{"decision":"deny","reason":"Blocked by RTK permission rule"}}"#
236	        );
237	        return Ok(());
238	    }
239	
240	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
241	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
242	        .unwrap_or_default();
243	
244	    match rewrite_command(cmd, &excluded, &transparent_prefixes) {
245	        Some(ref rewritten) => {
246	            audit_log("rewrite", cmd, rewritten);
247	            print_rewrite(rewritten);
248	        }
249	        None => print_allow(),
250	    }
251	
252	    Ok(())
253	}
254	
255	fn print_allow() {
256	    let _ = writeln!(io::stdout(), r#"{{"decision":"allow"}}"#);
257	}
258	
259	fn print_rewrite(cmd: &str) {
260	    let output = serde_json::json!({
261	        "decision": "allow",
262	        "hookSpecificOutput": {
263	            "tool_input": {
264	                "command": cmd
265	            }
266	        }
267	    });
268	    let _ = writeln!(io::stdout(), "{}", output);
269	}
