281	/// Escape newlines to prevent log-line injection in the pipe-delimited audit log.
282	fn sanitize_log_field(s: &str) -> String {
283	    s.replace('\\', "\\\\")
284	        .replace('|', "\\|")
285	        .replace('\n', "\\n")
286	        .replace('\r', "\\r")
287	}
288	
289	fn audit_log_inner(action: &str, original: &str, rewritten: &str) -> Option<()> {
290	    let home = dirs::home_dir()?;
291	    let dir = home.join(".local").join("share").join("rtk");
292	    std::fs::create_dir_all(&dir).ok()?;
293	    let path = dir.join("hook-audit.log");
294	    let mut file = std::fs::OpenOptions::new()
295	        .create(true)
296	        .append(true)
297	        .open(path)
298	        .ok()?;
299	    let ts = chrono::Local::now().format("%Y-%m-%dT%H:%M:%S");
300	    writeln!(
301	        file,
302	        "{} | {} | {} | {}",
303	        ts,
304	        action,
305	        sanitize_log_field(original),
306	        sanitize_log_field(rewritten)
307	    )
308	    .ok()
309	}
