311	// ── Claude Code native hook ────────────────────────────────────
312	
313	enum PayloadAction {
314	    Rewrite {
315	        cmd: String,
316	        rewritten: String,
317	        output: Value,
318	    },
319	    Skip {
320	        reason: &'static str,
321	        cmd: String,
322	    },
323	    Ignore,
324	}
325	
326	fn process_claude_payload(v: &Value) -> PayloadAction {
327	    let cmd = match v
328	        .pointer("/tool_input/command")
329	        .and_then(|c| c.as_str())
330	        .filter(|c| !c.is_empty())
331	    {
332	        Some(c) => c,
333	        None => return PayloadAction::Ignore,
334	    };
335	
336	    let verdict = permissions::check_command(cmd);
337	    if verdict == PermissionVerdict::Deny {
338	        return PayloadAction::Skip {
339	            reason: "skip:deny_rule",
340	            cmd: cmd.to_string(),
341	        };
342	    }
343	
344	    let rewritten = match get_rewritten(cmd) {
345	        Some(r) => r,
346	        None => {
347	            return PayloadAction::Skip {
348	                reason: "skip:no_match",
349	                cmd: cmd.to_string(),
350	            }
351	        }
352	    };
353	
354	    let updated_input = {
355	        let mut ti = v.get("tool_input").cloned().unwrap_or_else(|| json!({}));
356	        if let Some(obj) = ti.as_object_mut() {
357	            obj.insert("command".into(), Value::String(rewritten.clone()));
358	        }
359	        ti
360	    };
361	
362	    let mut hook_output = json!({
363	        "hookEventName": PRE_TOOL_USE_KEY,
364	        "permissionDecisionReason": "RTK auto-rewrite",
365	        "updatedInput": updated_input
366	    });
367	
368	    if verdict == PermissionVerdict::Allow {
369	        hook_output
370	            .as_object_mut()
371	            .unwrap()
372	            .insert("permissionDecision".into(), json!("allow"));
373	    }
374	
375	    PayloadAction::Rewrite {
376	        cmd: cmd.to_string(),
377	        rewritten,
378	        output: json!({ "hookSpecificOutput": hook_output }),
379	    }
380	}
381	
382	/// Run the Claude Code PreToolUse hook natively.
383	pub fn run_claude() -> Result<()> {
384	    let input = read_stdin_limited()?;
385	
386	    let input = input.trim();
387	    if input.is_empty() {
388	        return Ok(());
389	    }
390	
391	    let v: Value = match serde_json::from_str(input) {
392	        Ok(v) => v,
393	        Err(e) => {
394	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
395	            return Ok(());
396	        }
397	    };
398	
399	    let session_id = v
400	        .get("session_id")
401	        .and_then(|s| s.as_str())
402	        .unwrap_or("unknown")
403	        .to_string();
404	
405	    capture_provenance_best_effort(&session_id);
406	    capture_pr_metadata_best_effort(&session_id);
407	
408	    match process_claude_payload(&v) {
409	        PayloadAction::Rewrite {
410	            cmd,
411	            rewritten,
412	            output,
413	        } => {
414	            audit_log("rewrite", &cmd, &rewritten);
415	            let _ = writeln!(io::stdout(), "{output}");
416	        }
417	        PayloadAction::Skip { reason, cmd } => {
418	            audit_log(reason, &cmd, "");
419	        }
420	        PayloadAction::Ignore => {}
421	    }
422	
423	    Ok(())
424	}
