435	// ── Cursor native hook ─────────────────────────────────────────
436	
437	/// Cursor on Windows ships hook payloads with one or more leading
438	/// UTF-8 BOMs (`EF BB BF`, sometimes doubled), which serde_json
439	/// refuses to parse. Strip them defensively so the rewrite path keeps
440	/// working instead of silently returning `{}`.
441	fn strip_leading_bom(input: &str) -> &str {
442	    let mut s = input;
443	    while let Some(rest) = s.strip_prefix('\u{feff}') {
444	        s = rest;
445	    }
446	    s
447	}
448	
449	/// Run the Cursor Agent hook natively.
450	pub fn run_cursor() -> Result<()> {
451	    let input = read_stdin_limited()?;
452	
453	    let input = strip_leading_bom(&input).trim();
454	    if input.is_empty() {
455	        let _ = writeln!(io::stdout(), "{{}}");
456	        return Ok(());
457	    }
458	
459	    let v: Value = match serde_json::from_str(input) {
460	        Ok(v) => v,
461	        Err(_) => {
462	            let _ = writeln!(io::stdout(), "{{}}");
463	            return Ok(());
464	        }
465	    };
466	
467	    let cmd = match v
468	        .pointer("/tool_input/command")
469	        .and_then(|c| c.as_str())
470	        .filter(|c| !c.is_empty())
471	    {
472	        Some(c) => c.to_string(),
473	        None => {
474	            let _ = writeln!(io::stdout(), "{{}}");
475	            return Ok(());
476	        }
477	    };
478	
479	    let verdict = permissions::check_command(&cmd);
480	    if verdict == PermissionVerdict::Deny {
481	        audit_log("deny", &cmd, "");
482	        let _ = writeln!(io::stdout(), "{{}}");
483	        return Ok(());
484	    }
485	
486	    let rewritten = match get_rewritten(&cmd) {
487	        Some(r) => r,
488	        None => {
489	            let _ = writeln!(io::stdout(), "{{}}");
490	            return Ok(());
491	        }
492	    };
493	
494	    // Cursor preToolUse currently enforces allow/deny only and can ignore
495	    // updated_input when permission is "ask". Use "allow" for rewritten
496	    // commands unless the command is explicitly denied above.
497	    let decision = "allow";
498	
499	    audit_log("rewrite", &cmd, &rewritten);
500	
501	    // `continue: true` mirrors the shape of every other Cursor hook
502	    // (afterShellExecution, beforeSubmitPrompt, stop, ...). Cursor's
503	    // preToolUse panel renders the JSON it received; without this field
504	    // the panel collapses to `Output: {}` even though the rewrite ran,
505	    // which makes the hook look broken to users.
506	    let output = json!({
507	        "continue": true,
508	        "permission": decision,
509	        "updated_input": { "command": rewritten }
510	    });
511	    let _ = writeln!(io::stdout(), "{output}");
512	    Ok(())
513	}
