    /// Cost breakdown grouped by day (YYYY-MM-DD prefix of timestamp).
    pub fn summarize_by_day(&self) -> Result<Vec<CostSummary>> {
        let mut stmt = self.conn.prepare(
            "SELECT SUBSTR(timestamp, 1, 10) as key,
                    SUM(cost_usd), COUNT(*),
                    SUM(input_tokens), SUM(output_tokens)
             FROM cost_records
             GROUP BY key ORDER BY key ASC",
        )?;
        collect_summaries(&mut stmt)
    }

    /// Sum cost_usd for a specific developer since a given RFC3339 timestamp.
    ///
    /// Used by the budget policy engine to check per-developer period spend.
    pub fn accumulated_cost_by_dev(&self, dev_id: &str, since: &str) -> Result<f64> {
        let total: f64 = self.conn.query_row(
            "SELECT COALESCE(SUM(cost_usd), 0.0) FROM cost_records
             WHERE developer_id = ?1 AND timestamp >= ?2",
            rusqlite::params![dev_id, since],
            |row| row.get(0),
        )?;
        Ok(total)
    }

    /// Sum cost_usd for a specific project path since a given RFC3339 timestamp.
    ///
    /// Used by the budget policy engine to check per-project period spend.
    pub fn accumulated_cost_by_project(&self, project_path: &str, since: &str) -> Result<f64> {
        let total: f64 = self.conn.query_row(
            "SELECT COALESCE(SUM(cost_usd), 0.0) FROM cost_records
             WHERE project_path = ?1 AND timestamp >= ?2",
            rusqlite::params![project_path, since],
            |row| row.get(0),
        )?;
        Ok(total)
    }

    /// Sum all cost_usd since a given RFC3339 timestamp (used for team/global limits).
    pub fn total_cost_since(&self, since: &str) -> Result<f64> {
        let total: f64 = self.conn.query_row(
            "SELECT COALESCE(SUM(cost_usd), 0.0) FROM cost_records
             WHERE timestamp >= ?1",
            rusqlite::params![since],
            |row| row.get(0),
        )?;
        Ok(total)
    }
}

