//! `rtk budget` — budget governance status for the current project.
//!
//! Shows accumulated spend vs limits for all configured policy scopes.
//!
//! Usage:
//!   rtk budget           — human-readable table
//!   rtk budget --json    — machine-readable JSON

use anyhow::{Context, Result};
use colored::Colorize;
use serde::Serialize;

use crate::core::budget_policy::{
    BudgetPeriod, LimitAction, PolicyConfig, PolicyEngine, PolicyScope, Verdict, period_start,
};
use crate::core::cost_store::CostStore;

/// One row in the budget status table.
#[derive(Debug, Serialize)]
pub struct BudgetRow {
    pub scope: String,
    pub id: String,
    pub spent_usd: f64,
    pub limit_usd: f64,
    pub pct: f64,
    pub status: String,
}

pub fn run_budget(json: bool) -> Result<()> {
    let config = PolicyConfig::load();
    let store = CostStore::new().context("failed to open cost store")?;

    if config.limits.is_empty() {
        if json {
            println!("[]");
        } else {
            println!("{}", "Budget Policy".bold());
            println!("{}", "─".repeat(50));
            println!("No budget limits configured.");
            println!("Create .codeflow/budget.toml or ~/.config/rtk/budget.toml to set limits.");
            println!();
            println!("See: rtk data/budget-policy-example.toml for format reference.");
        }
        return Ok(());
    }

    let since = period_start(&config.global.period);
    let dev_id = whoami();
    let project = current_project();

    let mut rows: Vec<BudgetRow> = Vec::with_capacity(config.limits.len());

    for limit in &config.limits {
        let spent = match &limit.scope {
            PolicyScope::Developer => {
                let target = if limit.id == "*" { &dev_id } else { &limit.id };
                store.accumulated_cost_by_dev(target, &since).unwrap_or(0.0)
            }
            PolicyScope::Project => {
                let target = if limit.id == "*" { &project } else { &limit.id };
                store
                    .accumulated_cost_by_project(target, &since)
                    .unwrap_or(0.0)
            }
            PolicyScope::Team => store.total_cost_since(&since).unwrap_or(0.0),
        };

        let pct = if limit.max_usd > 0.0 {
            (spent / limit.max_usd) * 100.0
        } else {
            0.0
        };

        let g = &config.global;
        let status = if pct >= g.block_at_pct && limit.action_on_exceed == LimitAction::Block {
            "BLOCKED"
        } else if pct >= g.warn_at_pct {
            "WARN"
        } else {
            "OK"
        };

        let scope_label = match &limit.scope {
            PolicyScope::Developer => "developer",
            PolicyScope::Project => "project",
            PolicyScope::Team => "team",
        };

        rows.push(BudgetRow {
            scope: scope_label.to_string(),
            id: limit.id.clone(),
            spent_usd: spent,
            limit_usd: limit.max_usd,
            pct,
            status: status.to_string(),
        });
    }

    if json {
        println!("{}", serde_json::to_string_pretty(&rows)?);
        return Ok(());
    }

    // Human-readable table
    let period_label = match config.global.period {
        BudgetPeriod::Monthly => "monthly",
        BudgetPeriod::Weekly => "weekly",
        BudgetPeriod::Daily => "daily",
    };

    println!("{}", "Budget Status".bold());
    println!(
        "  Period: {}  |  Warn at: {}%  |  Block at: {}%",
        period_label,
        config.global.warn_at_pct as u32,
        config.global.block_at_pct as u32,
    );
    println!("{}", "─".repeat(72));
    println!(
        "  {:<12} {:<24} {:>10} {:>10} {:>8} {:>8}",
        "SCOPE".bold(),
        "ID".bold(),
        "SPENT".bold(),
        "LIMIT".bold(),
        "PCT".bold(),
        "STATUS".bold(),
    );
    println!("  {}", "─".repeat(68));

    for row in &rows {
        let status_colored = match row.status.as_str() {
            "BLOCKED" => row.status.red().bold().to_string(),
            "WARN" => row.status.yellow().bold().to_string(),
            _ => row.status.green().to_string(),
        };

        let pct_colored = {
            let s = format!("{:.1}%", row.pct);
            if row.pct >= config.global.block_at_pct {
                s.red().to_string()
            } else if row.pct >= config.global.warn_at_pct {
                s.yellow().to_string()
            } else {
                s.green().to_string()
            }
        };

        println!(
            "  {:<12} {:<24} {:>10} {:>10} {:>8} {:>8}",
            truncate(&row.scope, 12),
            truncate(&row.id, 24),
            format_usd(row.spent_usd).yellow().to_string(),
            format_usd(row.limit_usd),
            pct_colored,
            status_colored,
        );
    }

    // Summary verdict
    let engine = PolicyEngine::new(config);
    let verdict = engine.evaluate(&store, &dev_id, &project);
    println!();
    match verdict {
        Verdict::Allow => println!("  {}", "All limits OK".green()),
        Verdict::Warn(msg) => println!("  {}", format!("Warning: {}", msg).yellow()),
        Verdict::Block(msg) => println!("  {}", format!("BLOCKED: {}", msg).red().bold()),
    }

    Ok(())
}

// ── Helpers ───────────────────────────────────────────────────────────────────

fn format_usd(amount: f64) -> String {
    format!("${:.4}", amount)
}

fn truncate(s: &str, max: usize) -> String {
    if s.len() <= max {
        s.to_string()
    } else {
        let end = s
            .char_indices()
            .take_while(|(i, _)| *i < max.saturating_sub(2))
            .last()
            .map(|(i, c)| i + c.len_utf8())
            .unwrap_or(0);
        format!("{}..", &s[..end])
    }
}

fn whoami() -> String {
    std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .unwrap_or_else(|_| "unknown".to_string())
}

/// Derive a short project name from the current working directory.
fn current_project() -> String {
    std::env::current_dir()
        .ok()
        .and_then(|p| {
            p.file_name()
                .map(|n| n.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "unknown".to_string())
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn format_usd_four_decimals() {
        assert_eq!(format_usd(0.015), "$0.0150");
        assert_eq!(format_usd(1.0), "$1.0000");
    }

    #[test]
    fn truncate_short_unchanged() {
        assert_eq!(truncate("hello", 10), "hello");
    }

    #[test]
    fn truncate_long_gets_ellipsis() {
        let r = truncate("abcdefghijklmnop", 8);
        assert!(r.len() <= 8);
        assert!(r.ends_with(".."));
    }

    #[test]
    fn status_output_no_limits_text() {
        // With no limits configured (default) run_budget should succeed without panicking.
        // We point RTK_COST_DB at a temp file so no real DB is touched.
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("cost.db");
        std::env::set_var("RTK_COST_DB", db.to_str().unwrap());
        let result = run_budget(false);
        std::env::remove_var("RTK_COST_DB");
        assert!(result.is_ok());
    }

    #[test]
    fn status_output_json_empty_store() {
        let dir = tempfile::tempdir().unwrap();
        let db = dir.path().join("cost.db");
        std::env::set_var("RTK_COST_DB", db.to_str().unwrap());
        let result = run_budget(true);
        std::env::remove_var("RTK_COST_DB");
        assert!(result.is_ok());
    }
}

