use crate::core::budget_policy::{PolicyConfig, PolicyEngine, Verdict};
use crate::core::content_hash;
use crate::core::cost_store::CostStore;
use crate::core::pr_linker;
use crate::core::provenance::{self, ProvenanceStore};
use crate::discover::registry::{has_heredoc, rewrite_command};

// ── Budget check (PreToolUse) ──────────────────────────────────────────────

/// Fail-open budget check. Returns true if the tool call should be BLOCKED.
///
/// Skipped entirely when RTK_BUDGET=0. On any internal error the function
/// logs a warning to stderr and returns false (allow), per fail-open policy.
fn check_budget_best_effort() -> bool {
    if std::env::var("RTK_BUDGET").as_deref() == Ok("0") {
        return false;
    }
    match check_budget() {
        Ok(blocked) => blocked,
        Err(e) => {
            let _ = writeln!(io::stderr(), "[rtk budget] warning: {e}");
            false // fail-open
        }
    }
}

fn check_budget() -> anyhow::Result<bool> {
    let store = CostStore::new()?;
    let config = PolicyConfig::load();
    let engine = PolicyEngine::new(config);

    let dev_id = std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .unwrap_or_else(|_| "unknown".to_string());

    let project = std::env::current_dir()
        .ok()
        .and_then(|p| p.file_name().map(|n| n.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "unknown".to_string());

    match engine.evaluate(&store, &dev_id, &project) {
        Verdict::Block(msg) => {
            let _ = writeln!(
                io::stderr(),
                "[rtk budget] BLOCKED: {} — set RTK_BUDGET=0 to disable checks",
                msg
            );
            Ok(true)
        }
        Verdict::Warn(msg) => {
            let _ = writeln!(io::stderr(), "[rtk budget] WARNING: {}", msg);
            Ok(false)
        }
        Verdict::Allow => Ok(false),
    }
}

/// Run the Claude Code PreToolUse hook natively.
pub fn run_claude() -> Result<()> {

let session_id = v
    .get("session_id")
    .and_then(|s| s.as_str())
    .unwrap_or("unknown")
    .to_string();

// Budget check runs first — a Block verdict returns early before any rewrite.
if check_budget_best_effort() {
    return Ok(());
}

capture_provenance_best_effort(&session_id);
capture_pr_metadata_best_effort(&session_id);

