#[test]
fn budget_check_does_not_block_with_empty_db() {
    // Empty DB + default config (no limits) = fail-open / Allow
    let dir = tempfile::tempdir().unwrap();
    let db = dir.path().join("cost.db");
    std::env::set_var("RTK_COST_DB", db.to_str().unwrap());
    let blocked = check_budget_best_effort();
    std::env::remove_var("RTK_COST_DB");
    assert!(!blocked, "empty DB with no limits must not block");
}

#[test]
fn budget_check_skipped_when_rtk_budget_zero() {
    std::env::set_var("RTK_BUDGET", "0");
    let blocked = check_budget_best_effort();
    std::env::remove_var("RTK_BUDGET");
    assert!(!blocked, "RTK_BUDGET=0 must always skip check");
}
